# -*- coding: utf-8 -*-
from odoo import api, fields, models, _
from odoo.exceptions import UserError, ValidationError


class LibraryBook(models.Model):
    _name = 'library.book'
    _description = 'Library Book'      # required, or a warning is logged
    _order = 'name'

    name = fields.Char(string='Title', required=True)
    active = fields.Boolean(default=True)
    date_published = fields.Date()
    page_count = fields.Integer()
    price = fields.Float(digits=(12, 2))
    state = fields.Selection([
        ('draft', 'Draft'),
        ('available', 'Available'),
        ('lost', 'Lost'),
    ], default='draft', required=True)
    partner_id = fields.Many2one('res.partner', string='Publisher', ondelete='set null')
    tag_ids = fields.Many2many('library.book.tag', string='Tags')
    line_ids = fields.One2many('library.book.line', 'book_id')
    total_pages = fields.Integer(compute='_compute_total_pages', store=True)

    @api.depends('line_ids.pages')
    def _compute_total_pages(self):
        for book in self:
            book.total_pages = sum(book.line_ids.mapped('pages'))

    @api.constrains('page_count')
    def _check_page_count(self):
        for book in self:
            if book.page_count < 0:
                raise ValidationError(_("Page count cannot be negative."))

# name_get() no longer exists (removed in 17). Override the display_name compute:
    @api.depends('name', 'reference')
    def _compute_display_name(self):
        for record in self:
            record.display_name = f"[{record.reference}] {record.name}"
# Reading labels: use record.display_name (never .name_get()).

class SaleOrder(models.Model):
    _inherit = 'sale.order'          # NO _name: extend in place

    delivery_note = fields.Text()

    def action_confirm(self):
        # always call super() and return its result
        result = super().action_confirm()
        for order in self:
            if order.delivery_note:
                order.message_post(body=order.delivery_note)
        return result

# -*- coding: utf-8 -*-
from odoo import http
from odoo.http import request


class LibraryController(http.Controller):

    @http.route('/library/books', type='http', auth='user', website=False)
    def list_books(self, **kwargs):
        books = request.env['library.book'].search([], limit=50)
        return request.make_json_response([
            {'id': b.id, 'name': b.name} for b in books])

    @http.route('/library/api/borrow', type='jsonrpc', auth='user', methods=['POST'])
    def borrow(self, book_id, **kwargs):
        # Odoo 19: type='jsonrpc' (the old type='json' alias still logs a warning)
        book = request.env['library.book'].browse(int(book_id)).exists()
        if not book:
            return {'error': 'not found'}
        book.action_borrow()
        return {'ok': True}
# Controllers live in controllers/*.py, imported from controllers/__init__.py,
# which the module __init__.py imports too.

class LibraryLoanWizard(models.TransientModel):
    _name = 'library.loan.wizard'
    _description = 'Borrow Books Wizard'

    book_ids = fields.Many2many('library.book', required=True)
    partner_id = fields.Many2one('res.partner', required=True)

    def action_confirm(self):
        self.ensure_one()
        for book in self.book_ids:
            self.env['library.loan'].create({
                'book_id': book.id, 'partner_id': self.partner_id.id})
        return {'type': 'ir.actions.act_window_close'}

# view: a normal <form> with <footer><button name="action_confirm"
# type="object" string="Confirm" class="btn-primary"/></footer>
# action: <record model="ir.actions.act_window"> with
#   <field name="target">new</field>  (opens as dialog)
# TransientModels still need an ir.model.access.csv line.

/** static/src/dashboard/library_dashboard.js */
import { Component, useState, onWillStart } from "@odoo/owl";
import { registry } from "@web/core/registry";
import { useService } from "@web/core/utils/hooks";
// A client-action component receives standard action props (action, actionId,
// className...). Odoo 19: spread standardActionServiceProps — NEVER `static
// props = {}` (that fails prop validation in debug mode).
import { standardActionServiceProps } from "@web/webclient/actions/action_service";

export class LibraryDashboard extends Component {
    static template = "library_management.LibraryDashboard";
    static props = { ...standardActionServiceProps };

    setup() {
        this.orm = useService("orm");
        this.state = useState({ rows: [], filter: "all" });
        onWillStart(() => this.load());
    }

    async load() {
        // DATA CONTRACT: the backend method must return EVERY field the UI reads
        // — including any field you filter/group by client-side. Here each row
        // carries `category` precisely so the filter below can work.
        this.state.rows = await this.orm.call("library.book", "get_dashboard_data", []);
    }

    get visibleRows() {
        const f = this.state.filter;
        return f === "all" ? this.state.rows : this.state.rows.filter((r) => r.category === f);
    }

    setFilter(f) { this.state.filter = f; }   // reactive: getter re-runs on change
}
registry.category("actions").add("library_dashboard_action", LibraryDashboard);

/* Template (static/src/dashboard/library_dashboard.xml) — t-name MUST match
   the static template string above:
<templates xml:space="preserve">
    <t t-name="library_management.LibraryDashboard">
        <div class="o_library_dashboard p-3">
            <button t-att-class="state.filter==='revenue' ? 'btn-primary' : 'btn-light'"
                    t-on-click="() => this.setFilter('revenue')">Revenue</button>
            <t t-foreach="visibleRows" t-as="row" t-key="row.id">
                <div t-esc="row.name"/>
            </t>
        </div>
    </t>
</templates>
Manifest assets: 'web.assets_backend': ['library_management/static/src/**/*']
The client action opens via <record model="ir.actions.client"> tag=the registry key,
or a menu with action pointing to it. */

/** static/src/js/message_patch.js */
import { patch } from "@web/core/utils/patch";
import { Message } from "@mail/core/common/message";

patch(Message.prototype, {
    setup() {
        super.setup(...arguments);
        // extra setup here
    },
    get customLabel() {
        return this.props.message.isSelfAuthored ? "me" : "other";
    },
});
// Patch prototypes for methods/getters; patch the class itself
// (patch(Message, {...})) only for static properties like components.

# tests/test_library.py  (tests/__init__.py: from . import test_library)
from odoo.tests import TransactionCase, tagged


@tagged('post_install', '-at_install')
class TestLibraryBook(TransactionCase):

    @classmethod
    def setUpClass(cls):
        super().setUpClass()
        cls.book = cls.env['library.book'].create({'name': 'Dune'})

    def test_publish_flow(self):
        self.book.action_publish()
        self.assertEqual(self.book.state, 'available')

    def test_negative_pages_blocked(self):
        with self.assertRaises(Exception):
            self.book.page_count = -1
# Run: odoo-bin -d db -u library_management --test-enable --stop-after-init

# A STORED computed field whose value comes from a search() on ANOTHER model has
# a dependency @api.depends CANNOT express — Odoo only recomputes stored fields
# when a depended-on field ON THE RECORD (or a traversed relation) changes.
# So the stored value goes STALE when the other model's data changes.
class ResPartner(models.Model):
    _inherit = 'res.partner'
    loyalty_tier = fields.Selection(..., compute='_compute_loyalty_tier', store=True)

    @api.depends('loyalty_points', 'loyalty_tier_manual')
    def _compute_loyalty_tier(self):
        for p in self:
            if p.loyalty_tier_manual:
                continue
            rule = self.env['loyalty.tier.rule'].sudo().search(
                [('min_points', '<=', p.loyalty_points)], order='min_points desc', limit=1)
            p.loyalty_tier = rule.tier if rule else 'bronze'

# Recompute from the OTHER model's write/create/unlink so edits propagate:
class LoyaltyTierRule(models.Model):
    _name = 'loyalty.tier.rule'

    def write(self, vals):
        res = super().write(vals)
        if {'min_points', 'tier'} & set(vals):
            self.env['res.partner'].search(
                [('loyalty_tier_manual', '=', False)])._compute_loyalty_tier()
        return res
